     1→package com.danawa.search.analysis.korean
     2→
     3→import com.danawa.search.analysis.dict.ProductNameDictionary
     4→import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
     5→import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
