     9→
    10→import org.elasticsearch.common.logging.Loggers
    11→import java.util.PriorityQueue
    12→
    13→/**
    14→ * Korean word extractor using CYK-style dynamic programming.
    15→ * Extracts morphemes from Korean text using a probability-based scoring system.
    16→ */
    17→class KoreanWordExtractor @JvmOverloads constructor(
    18→    private var koreanDict: ProductNameDictionary?,
    19→    tabularSize: Int = 20
    20→) {
    21→    private val tabular: Array<Array<PosTagProbEntry?>>
    22→    private val status: IntArray
    23→    private val josaSet: MutableSet<CharVector>
    24→
    25→    // 최상의 후보가 만들어지면 바로 리턴. 기본 true
    26→    var fastResultOption: Boolean = true
    27→    // 발견되었는지 여부
    28→    private var fastResultFound: Boolean = false
    29→    private var remnantOffset: Int = 0
    30→    private var remnantLength: Int = 0
    31→    private var isUnicode: Boolean = false
    32→    private val charVector = CharVector()
    33→    private val tabularStringer: TabularStringer
    34→    private val entryStringer: EntryStringer
    35→
    36→    private val queue = PriorityQueue<ExtractedEntry>(8) { o1, o2 ->
    37→        (o2.totalScore() - o1.totalScore()).toInt()
    38→    }
    39→
    40→    private val result: MutableList<ExtractedEntry> = mutableListOf()
    41→
    42→    protected var source: CharArray = CharArray(0)
    43→    protected var offset: Int = 0
    44→    protected var length: Int = 0
    45→
    46→    init {
    47→        tabular = Array(tabularSize) { row ->
    48→            arrayOfNulls(row + 2)
    49→        }
    50→        status = IntArray(tabularSize)
    51→        josaSet = mutableSetOf()
    52→        val josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도"
    53→        for (j in josaList.split("\\s".toRegex())) {
    54→            josaSet.add(CharVector(j))
    55→        }
    56→        tabularStringer = TabularStringer()
    57→        entryStringer = EntryStringer()
    58→    }
    59→
    60→    fun dictionary(): ProductNameDictionary? = koreanDict
    61→
    62→    fun setKoreanDic(koreanDict: ProductNameDictionary?) {
    63→        this.koreanDict = koreanDict
    64→    }
    65→
    66→    // Property setter is generated automatically by Kotlin for 'var fastResultOption'
    67→
    68→    /**
    69→     * 음절을 조합하여 사전에서 찾아준다. 찾은 단어와 tag는 table에 저장한다.
    70→     */
    71→    private fun doSegment(): ExtractedEntry? {
    72→        val cv = CharVector(source, offset, length)
    73→        // 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
    74→        if (length == 1) {
    75→            val tag = koreanDict?.find(cv)
    76→            if (tag != null) {
    77→                return ExtractedEntry(length - 1, length, tag[0], offset)
    78→            }
    79→            return when {
    80→                isDigit(cv) -> ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
    81→                isSymbol(cv) -> ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
    82→                else -> ExtractedEntry(length - 1, length, TagProb.UNK, offset)
    83→            }
    84→        }
    85→        val tag = koreanDict?.find(cv)
    86→        if (tag != null) {
    87→            return ExtractedEntry(length - 1, length, tag[0], offset)
    88→        }
    89→        val start = length - 1
    90→        for (row in start downTo 0) {
    91→            for (column in (row + 1) downTo 1) {
    92→                cv.init(offset + row - column + 1, column)
    93→                var isAlpha = false
    94→                when {
    95→                    isDigit(cv) -> {
    96→                        tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
    97→                        status[row]++
    98→                    }
    99→                    isSymbol(cv) -> {
   100→                        tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
   101→                        status[row]++
   102→                    }
   103→                    else -> {
   104→                        if (isAlpha(cv)) {
   105→                            if (column == 1) {
   106→                                tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
   107→                                continue
   108→                            }
   109→                            isAlpha = true
   110→                        }
   111→                        val tagList = koreanDict?.find(cv)
   112→                        if (tagList != null) {
   113→                            if (column == length) {
   114→                                return ExtractedEntry(row, column, tagList[0], offset)
   115→                            }
   116→                            var chainedEntry: PosTagProbEntry? = null
   117→                            for (i in tagList.indices) {
   118→                                val tagProb = tagList[i]
   119→                                if (i == 0) {
   120→                                    chainedEntry = PosTagProbEntry(tagProb)
   121→                                    tabular[row][column] = chainedEntry
   122→                                } else {
   123→                                    chainedEntry = chainedEntry?.next(tagProb)
   124→                                }
   125→                            }
   126→                            status[row]++
   127→                        } else {
   128→                            tabular[row][column] = if (isAlpha) PosTagProbEntry(TagProb.ALPHA) else null
   129→                        }
   130→
   131→                        if (column < 3) {
   132→                            if (josaSet.contains(cv)) {
   133→                                val entry = PosTagProbEntry(TagProb.JOSA)
   134→                                if (tabular[row][column] == null) {
   135→                                    tabular[row][column] = entry
   136→                                } else {
   137→                                    entry.next = tabular[row][column]
   138→                                    tabular[row][column] = entry
   139→                                }
   140→                                status[row]++
   141→                            }
   142→                        }
   143→                    }
   144→                }
   145→            }
   146→        }
   147→        return null
   148→    }
   149→
   150→    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
   151→        for (inx in 0 until length) {
   152→            val ch = buffer[offset + inx]
   153→            if (ch.code > 127) {
   154→                return true
   155→            }
   156→        }
   157→        return false
   158→    }
   159→
   160→    private fun isDigit(cv: CharVector): Boolean {
   161→        for (i in 0 until cv.length) {
   162→            val ch = cv[i]
   163→            if (ch !in '0'..'9') {
   164→                return false
   165→            }
   166→        }
   167→        return true
   168→    }
   169→
   170→    private fun isAlpha(cv: CharVector): Boolean {
   171→        for (i in 0 until cv.length) {
   172→            val ch = cv[i]
   173→            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
   174→                return false
   175→            }
   176→        }
   177→        return true
   178→    }
   179→
   180→    private fun isSymbol(cv: CharVector): Boolean {
   181→        for (i in 0 until cv.length) {
   182→            val chInt = cv[i].code
   183→            if (Character.isLetterOrDigit(chInt)) {
   184→                return false
   185→            }
   186→        }
   187→        return true
   188→    }
   189→
   190→    private fun makeResult() {
   191→        var headRow = -1
   192→        for (row in (length - 1) downTo 0) {
   193→            if (status[row] > 0) {
   194→                headRow = row
   195→                break
   196→            }
   197→        }
   198→
   199→        try {
   200→            if (headRow == -1) {
   201→                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
   202→                return
   203→            }
   204→            if (headRow < length - 1) {
   205→                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
   206→                connectAllTo(headRow, tail)
   207→            } else {
   208→                connectAllTo(headRow, null)
   209→            }
   210→            var tail: ExtractedEntry?
   211→            while (queue.poll().also { tail = it } != null) {
   212→                val connectRow = tail!!.row() - tail!!.column()
   213→                if (status[connectRow] > 0) {
   214→                    connectAllTo(connectRow, tail)
   215→                } else {
   216→                    connectTo(null, connectRow, -1, tail)
   217→                }
   218→            }
   219→        } catch (e: AnalyzeExceedException) {
   220→            logger.debug("Analyze exceed : " + e.message)
   221→        }
   222→    }
   223→
   224→    @Throws(AnalyzeExceedException::class)
   225→    private fun connectAllTo(headRow: Int, tail: ExtractedEntry?): Int {
   226→        val rowData = tabular[headRow]
   227→        var found = 0
   228→        for (headColumn in (headRow + 1) downTo 1) {
   229→            if (rowData[headColumn] != null) {
   230→                val tagEntry = rowData[headColumn]!!
   231→                entryStringer.set(tagEntry, source, headRow, headColumn, offset)
   232→                if (tagEntry.tagProb?.posTag() != PosTag.ALPHA) {
   233→                    connectTo(tagEntry, headRow, headColumn, tail)
   234→                    found++
   235→                }
   236→            }
   237→            if (found >= status[headRow]) {
   238→                break
   239→            }
   240→        }
   241→        if (!isUnicode) {
   242→            val iter = result.iterator()
   243→            while (iter.hasNext()) {
   244→                val entry = iter.next()
   245→                if (entry.last().posTag() == PosTag.UNK) {
   246→                    iter.remove()
   247→                }
   248→            }
   249→        }
   250→        return found
   251→    }
   252→
   253→    @Throws(AnalyzeExceedException::class)
   254→    private fun connectTo(
   255→        headTagEntry: PosTagProbEntry?,
   256→        headRow: Int,
   257→        headColumn: Int,
   258→        tail: ExtractedEntry?
   259→    ): Int {
   260→        var currentEntry = headTagEntry
   261→        if (tail == null) {
   262→            var found = 0
   263→            while (currentEntry != null) {
   264→                val headEntry = ExtractedEntry(headRow, headColumn, currentEntry.get()!!, offset)
   265→                if (headEntry.row() - headEntry.column() < 0) {
   266→                    addResult(headEntry)
   267→                } else {
   268→                    addQueue(headEntry)
   269→                }
   270→                currentEntry = currentEntry.next
   271→                found++
   272→            }
   273→            return found
   274→        }
   275→
   276→        if (currentEntry == null) {
   277→            for (column in 1..(headRow + 1)) {
   278→                val row2 = headRow - column
   279→                if (row2 < 0 || status[row2] > 0) {
   280→                    // 2014-1-27처리..
   281→                }
   282→            }
   283→            return 1
   284→        }
   285→
   286→        var found = 0
   287→        while (currentEntry != null) {
   288→            if (isConnectableByRule(currentEntry.get()!!, headRow, headColumn, tail)) {
   289→                val newTail = modifyAndConnect(currentEntry.get()!!, headRow, headColumn, tail)
   290→                if (newTail != null) {
   291→                    if (newTail.row() - newTail.column() < 0) {
   292→                        addResult(newTail)
   293→                    } else {
   294→                        addQueue(newTail)
   295→                    }
   296→                    found++
   297→                }
   298→            }
   299→            currentEntry = currentEntry.next
   300→        }
   301→        return found
   302→    }
