   304→    @Throws(AnalyzeExceedException::class)
   305→    protected fun addQueue(entry: ExtractedEntry) {
   306→        if (fastResultFound) {
   307→            return
   308→        }
   309→        queue.add(entry)
   310→        if (queue.size >= QUEUE_MAX) {
   311→            throw AnalyzeExceedException("Queue size exceed ${queue.size} : ${String(source)}")
   312→        }
   313→    }
