   316→    protected fun addResult(entry: ExtractedEntry) {
   317→        val e = finalCheck(entry) ?: return
   318→        result.add(entry)
   319→
   320→        if (fastResultOption && length > 6) {
   321→            fastResultFound = true
   322→            queue.clear()
   323→        }
   324→
   325→        if (result.size >= RESULT_MAX) {
   326→            val tmpResult = getHighResult()
   327→            result.clear()
   328→            if (tmpResult != null) {
   329→                result.add(tmpResult)
   330→            }
   331→        }
