   338→    fun setInput(buffer: CharArray, offset: Int, length: Int): Int {
   339→        var len = length
   340→        remnantOffset = 0
   341→        remnantLength = 0
   342→        isUnicode = isUnicode(buffer, offset, len)
   343→        status.fill(0)
   344→        for (row in tabular.indices) {
   345→            for (col in tabular[row].indices) {
   346→                tabular[row][col] = null
   347→            }
   348→        }
   349→        result.clear()
   350→
   351→        var type: String? = null
   352→        var ptype: String? = null
   353→        var pptype: String?
   354→
   355→        if (len > tabular.size) {
   356→            logger.trace("LENGTH IS OVER THAN {} / {} / {}", len, tabular.size, offset)
   357→            for (inx in (offset + len) downTo (offset + 1)) {
   358→                pptype = ptype
   359→                ptype = type
   360→                type = TokenTypes.getType(buffer[inx - 1].code)
   361→                if (logger.isTraceEnabled) {
   362→                    logger.trace(
   363→                        "PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
   364→                        inx - offset,
   365→                        (pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER)),
   366→                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
   367→                        (type != null), (pptype != null),
   368→                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
   369→                        (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER))
   370→                    )
   371→                }
   372→                if (((pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER))
   373→                            && (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&')
   374→                            && (type != null))
   375→                    || ((pptype != null) && (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&')
   376→                            && (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER)))
   377→                ) {
   378→                    logger.trace("LENGTH:{} / {}", len - offset, tabular.size)
   379→                    len = inx - offset
   380→                    if (len <= tabular.size) {
   381→                        logger.trace("BREAK INTO {}", len)
   382→                        break
   383→                    }
   384→                }
   385→            }
   386→            if (len > tabular.size) {
   387→                type = null
   388→                for (inx in offset until (offset + len)) {
   389→                    ptype = type
   390→                    type = TokenTypes.getType(buffer[inx].code)
   391→                    if (ptype != null && (
   392→                                ((type == TokenTypes.ALPHA || type == TokenTypes.NUMBER || type == TokenTypes.SYMBOL)
   393→                                        && !(ptype == TokenTypes.ALPHA || ptype == TokenTypes.NUMBER || ptype == TokenTypes.SYMBOL))
   394→                                        || (!(type == TokenTypes.ALPHA || type == TokenTypes.NUMBER || type == TokenTypes.SYMBOL)
   395→                                        && (ptype == TokenTypes.ALPHA || ptype == TokenTypes.NUMBER || ptype == TokenTypes.SYMBOL))
   396→                                )
   397→                    ) {
   398→                        len = inx - offset
   399→                    }
   400→                }
   401→            }
   402→
   403→            if (len > tabular.size) {
   404→                if (logger.isTraceEnabled) {
   405→                    logger.trace(
   406→                        "CUT TABULAR SIZE : {}/ {} -> {}", len, String(buffer, offset, len),
   407→                        String(buffer, offset, tabular.size)
   408→                    )
   409→                }
   410→                remnantOffset = tabular.size
   411→                remnantLength = len - tabular.size
   412→                len = tabular.size
   413→            }
   414→        }
   415→        return setInput0(buffer, offset, len)
   416→    }
