   458→    private fun getHighResult(): ExtractedEntry? {
   459→        var highEntry: ExtractedEntry? = null
   460→        for (k in result.indices) {
   461→            var entry: ExtractedEntry? = result[k]
   462→            entry = finalCheck(entry!!) ?: continue
   463→            charVector.init(source, entry.offset(), entry.column())
   464→
   465→            if (highEntry == null) {
   466→                highEntry = entry
   467→            } else {
   468→                if (isBetterThan(entry, highEntry)) {
   469→                    highEntry = entry
   470→                }
   471→            }
   472→        }
   473→        return highEntry
