   128→        @JvmStatic
   129→        fun loadDictionary(env: Environment): ProductNameDictionary? {
   130→            // 플러그인 디렉토리 에서 설정파일을 찾도록 한다.
   131→            for (tries in 0 until 2) {
   132→                try {
   133→                    baseFile = if (tries == 0) {
   134→                        ResourceResolver.getResourceRoot(ProductNameDictionary::class.java)
   135→                    } else {
   136→                        // 설정파일이 플러그인 디렉토리에 존재하지 않는다면 검색엔진 conf 디렉토리에서 설정파일을 찾는다.
   137→                        env.configDir().toFile()
   138→                    }
   139→                    logger.debug("TESTING PRODUCT DICTIONARY BASE : {}", baseFile?.absolutePath)
   140→                    if (baseFile?.exists() == true) {
   141→                        logger.debug("PRODUCT DICTIONARY BASE : {}", baseFile?.absolutePath)
   142→                    }
   143→                } catch (e: Exception) {
   144→                    logger.error("", e)
   145→                    baseFile = null
   146→                    configFile = null
   147→                    continue
   148→                }
   149→                configFile = File(baseFile, ANALYSIS_PROP)
   150→                if (configFile?.exists() == true) {
   151→                    logger.debug("DICTIONARY PROPERTIES : {}", configFile?.absolutePath)
   152→                    break
   153→                } else {
   154→                    baseFile = null
   155→                    configFile = null
   156→                }
   157→            }
   158→            val finalConfigFile = configFile
   159→            if (finalConfigFile == null) {
   160→                logger.error("DICTIONARY PROPERTIES FILE NOT FOUND")
   161→                return null
   162→            }
   163→            val dictProp = ResourceResolver.readYmlConfig(finalConfigFile)
   164→            if (dictProp == null) {
   165→                logger.error("DICTIONARY PROPERTIES FILE NOT FOUND {}", finalConfigFile.absolutePath)
   166→            }
   167→            return loadDictionary(baseFile, dictProp)
   168→        }
