package com.danawa.search.analysis.dict

import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import com.danawa.search.analysis.korean.PreResult
import com.danawa.util.ContextStore
import com.danawa.util.ResourceResolver

import org.elasticsearch.client.internal.node.NodeClient
import org.elasticsearch.common.logging.Loggers
import org.elasticsearch.env.Environment
import org.json.JSONArray
import org.json.JSONObject

import java.io.File
import java.io.FileOutputStream
import java.util.TreeSet

class ProductNameDictionary(
    systemDictionary: Dictionary<TagProb, PreResult<CharSequence>>
) : CommonDictionary<TagProb, PreResult<CharSequence>>(systemDictionary) {

    abstract class DictionaryRepository {
        abstract fun getSource(type: String): Iterator<Array<CharSequence?>>
        abstract fun restore(type: String, ignoreCase: Boolean, wordSet: @JvmSuppressWildcards Set<CharSequence>)
        abstract fun close()
    }

    companion object {
        private val logger = Loggers.getLogger(ProductNameDictionary::class.java, "")

        // Type is now defined in DictionaryType.kt - use DictionaryType enum
        @JvmField
        val Type: Class<DictionaryType> = DictionaryType::class.java

        const val PRODUCT_NAME_DICTIONARY = "PRODUCT_NAME_DICTIONARY"

        const val DICT_UNIT_SYNONYM = "unit_synonym"
        const val DICT_UNIT = "unit"
        const val DICT_SPACE = "space"
        const val DICT_SYNONYM = "synonym"
        const val DICT_STOP = "stop"
        const val DICT_USER = "user"
        const val DICT_COMPOUND = "compound"
        const val DICT_MAKER = "maker"
        const val DICT_BRAND = "brand"
        const val DICT_CATEGORY = "category"

        private const val DICTIONARY_PATH = "dict/"
        private const val DICTIONARY_SUFFIX = ".dict"

        const val USER_DICT_PATH_OPTION = "user_dictionary"
        const val USER_DICT_RULES_OPTION = "user_dictionary_rules"

        private const val ANALYSIS_PROP = "product-name-dictionary.yml"
        private const val ATTR_DICTIONARY_BASE_PATH = "basePath"
        private const val ATTR_DICTIONARY_LIST = "dictionary"
        private const val ATTR_DICTIONARY_NAME = "name"
        private const val ATTR_DICTIONARY_TYPE = "type"
        private const val ATTR_DICTIONARY_TOKEN_TYPE = "tokenType"
        private const val ATTR_DICTIONARY_IGNORECASE = "ignoreCase"
        private const val ATTR_DICTIONARY_FILE_PATH = "filePath"
        private const val ATTR_DICTIONARY_SEQ = "seq"
        private const val ATTR_DICTIONARY_LABEL = "label"

        const val TAB = "\t"

        // Using String-based store key to break compile-time dependency on AnalysisProductNamePlugin
        const val CONTEXT_STORE_KEY = "AnalysisProductName"
        private val contextStore: ContextStore = ContextStore.getStore(CONTEXT_STORE_KEY)

        private var baseFile: File? = null
        private var configFile: File? = null

        private fun getDictionaryFile(envBase: File?, prop: JSONObject, basePath: String?): File {
            var localBaseFile: File? = null
            try {
                if (!basePath.isNullOrEmpty()) {
                    localBaseFile = File(basePath)
                }
                if (localBaseFile == null || !localBaseFile.exists()) {
                    localBaseFile = envBase
                }
            } catch (e: Exception) {
                logger.debug("DICTIONARY EXCEPTION : {} / {}", localBaseFile, e.message)
                localBaseFile = envBase
            }

            val dictionaryId = prop.optString(ATTR_DICTIONARY_NAME, "").trim()
            val path = prop.optString(ATTR_DICTIONARY_FILE_PATH, "").trim()
            var ret = File(localBaseFile, path)
            if (path.isEmpty() || !ret.exists()) {
                ret = File(File(envBase, DICTIONARY_PATH), "$dictionaryId$DICTIONARY_SUFFIX")
            }
            return ret
        }

        private fun getType(prop: JSONObject): DictionaryType? {
            val attribute = prop.optString(ATTR_DICTIONARY_TYPE, "").trim()
            return DictionaryType.values().find { it.name.equals(attribute, ignoreCase = true) }
        }

        private fun getIgnoreCase(prop: JSONObject): Boolean {
            return prop.optBoolean(ATTR_DICTIONARY_IGNORECASE, true)
        }

        private fun getTokenType(prop: JSONObject): String? {
            val attribute = prop.optString(ATTR_DICTIONARY_TOKEN_TYPE, "").trim()
            return TokenType.values().find { it.name.equals(attribute, ignoreCase = true) }?.name
        }

        private fun getLabel(prop: JSONObject): String? {
            return try {
                prop.optString(ATTR_DICTIONARY_LABEL, "").trim()
            } catch (e: Exception) {
                null
            }
        }

        private fun getSeq(prop: JSONObject): Int {
            return try {
                val attribute = prop.optString(ATTR_DICTIONARY_SEQ, "").trim()
                if (attribute.isNotEmpty()) attribute.toInt() else 0
            } catch (e: Exception) {
                0
            }
        }

        @JvmStatic
        fun loadDictionary(env: Environment): ProductNameDictionary? {
            // 플러그인 디렉토리 에서 설정파일을 찾도록 한다.
            for (tries in 0 until 2) {
                try {
                    baseFile = if (tries == 0) {
                        ResourceResolver.getResourceRoot(ProductNameDictionary::class.java)
                    } else {
                        // 설정파일이 플러그인 디렉토리에 존재하지 않는다면 검색엔진 conf 디렉토리에서 설정파일을 찾는다.
                        env.configDir().toFile()
                    }
                    logger.debug("TESTING PRODUCT DICTIONARY BASE : {}", baseFile?.absolutePath)
                    if (baseFile?.exists() == true) {
                        logger.debug("PRODUCT DICTIONARY BASE : {}", baseFile?.absolutePath)
                    }
                } catch (e: Exception) {
                    logger.error("", e)
                    baseFile = null
                    configFile = null
                    continue
                }
                configFile = File(baseFile, ANALYSIS_PROP)
                if (configFile?.exists() == true) {
                    logger.debug("DICTIONARY PROPERTIES : {}", configFile?.absolutePath)
                    break
                } else {
                    baseFile = null
                    configFile = null
                }
            }
            val finalConfigFile = configFile
            if (finalConfigFile == null) {
                logger.error("DICTIONARY PROPERTIES FILE NOT FOUND")
                return null
            }
            val dictProp = ResourceResolver.readYmlConfig(finalConfigFile)
            if (dictProp == null) {
                logger.error("DICTIONARY PROPERTIES FILE NOT FOUND {}", finalConfigFile.absolutePath)
            }
            return loadDictionary(baseFile, dictProp)
        }

        @JvmStatic
        fun loadDictionary(baseFile: File?, dictProp: JSONObject?): ProductNameDictionary? {
            if (dictProp == null) return null

            var dictionary: Dictionary<TagProb, PreResult<CharSequence>>? = null
            var commonDictionary: ProductNameDictionary? = null
            val dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST) ?: return null
            val basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH)

            // 시스템사전을 먼저 읽어오도록 한다.
            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                if (getType(row) == DictionaryType.SYSTEM) {
                    dictionary = loadSystemDictionary(baseFile!!, row, basePath)
                    commonDictionary = ProductNameDictionary(dictionary)
                    break
                }
            }

            if (commonDictionary == null) return null

            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                val dictionaryId = row.optString(ATTR_DICTIONARY_NAME)
                val type = getType(row) ?: continue
                val tokenType = getTokenType(row)
                val label = getLabel(row)
                val seq = getSeq(row)
                val dictFile = getDictionaryFile(baseFile, row, basePath)
                val ignoreCase = getIgnoreCase(row)
                var sourceDictionary: SourceDictionary<*>? = null
                logger.info("Dictionary Setting Name: {}, type: {}", label, type.name)

                when (type) {
                    DictionaryType.SET -> {
                        val setDictionary = SetDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(setDictionary.set(), tokenType)
                        }
                        sourceDictionary = setDictionary
                    }
                    DictionaryType.MAP -> {
                        val mapDictionary = MapDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(mapDictionary.map().keys, tokenType)
                        }
                        sourceDictionary = mapDictionary
                    }
                    DictionaryType.SYNONYM, DictionaryType.SYNONYM_2WAY -> {
                        val synonymDictionary = SynonymDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(synonymDictionary.getWordSet(), tokenType)
                        }
                        sourceDictionary = synonymDictionary
                    }
                    DictionaryType.SPACE -> {
                        val spaceDictionary = SpaceDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(spaceDictionary.getWordSet(), tokenType)
                        }
                        sourceDictionary = spaceDictionary
                    }
                    DictionaryType.CUSTOM -> {
                        val customDictionary = CustomDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(customDictionary.getWordSet(), tokenType)
                        }
                        sourceDictionary = customDictionary
                    }
                    DictionaryType.INVERT_MAP -> {
                        val invertMapDictionary = InvertMapDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(invertMapDictionary.map().keys, tokenType)
                        }
                        sourceDictionary = invertMapDictionary
                    }
                    DictionaryType.COMPOUND -> {
                        val compoundDictionary = CompoundDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
                        if (tokenType != null) {
                            commonDictionary.appendAdditionalNounEntry(compoundDictionary.map().keys, tokenType)
                        }
                        sourceDictionary = compoundDictionary
                    }
                    DictionaryType.SYSTEM -> { /* ignore */ }
                }

                if (sourceDictionary != null) {
                    commonDictionary.addDictionary(dictionaryId, sourceDictionary)
                }
            }
            return commonDictionary
        }

        @JvmStatic
        fun reloadDictionary() {
            val localBaseFile = baseFile
            val localConfigFile = configFile
            if (localBaseFile == null || localConfigFile == null) {
                logger.error("DICTIONARY NOT LOADED!")
                return
            }
            val newCommonDictionary = loadDictionary(localBaseFile, ResourceResolver.readYmlConfig(localConfigFile))
            val commonDictionary = contextStore.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)
                ?: return

            // 1. commonDictionary에 systemdictionary셋팅.
            newCommonDictionary?.let { commonDictionary.reset(it) }
            // 2. dictionaryMap 에 셋팅.
            val dictionaryMap = commonDictionary.getDictionaryMap()

            for ((dictionaryId, dictionary) in dictionaryMap) {
                when {
                    dictionary.javaClass.isAssignableFrom(SetDictionary::class.java) -> {
                        val setDictionary = dictionary as SetDictionary
                        val newDictionary = newCommonDictionary?.getDictionary(dictionaryId, SetDictionary::class.java)
                        newDictionary?.let { setDictionary.setSet(it.set()) }
                    }
                    dictionary.javaClass.isAssignableFrom(MapDictionary::class.java) -> {
                        val mapDictionary = dictionary as MapDictionary
                        val newDictionary = newCommonDictionary?.getDictionary(dictionaryId, MapDictionary::class.java)
                        newDictionary?.let { mapDictionary.setMap(it.map()) }
                    }
                    dictionary.javaClass.isAssignableFrom(SynonymDictionary::class.java) -> {
                        val synonymDictionary = dictionary as SynonymDictionary
                        val newDictionary = newCommonDictionary?.getDictionary(dictionaryId, SynonymDictionary::class.java)
                        newDictionary?.let {
                            synonymDictionary.setMap(it.map())
                            synonymDictionary.setWordSet(it.getWordSet())
                        }
                    }
                    dictionary.javaClass.isAssignableFrom(SpaceDictionary::class.java) -> {
                        val spaceDictionary = dictionary as SpaceDictionary
                        val newDictionary = newCommonDictionary?.getDictionary(dictionaryId, SpaceDictionary::class.java)
                        newDictionary?.let {
                            spaceDictionary.setMap(it.map())
                            spaceDictionary.setWordSet(it.getWordSet())
                        }
                    }
                    dictionary.javaClass.isAssignableFrom(CustomDictionary::class.java) -> {
                        val customDictionary = dictionary as CustomDictionary
                        val newDictionary = newCommonDictionary?.getDictionary(dictionaryId, CustomDictionary::class.java)
                        newDictionary?.let {
                            customDictionary.setMap(it.map())
                            customDictionary.setWordSet(it.getWordSet())
                        }
                    }
                    dictionary.javaClass.isAssignableFrom(CompoundDictionary::class.java) -> {
                        val compoundDictionary = dictionary as CompoundDictionary
                        val newDictionary = newCommonDictionary?.getDictionary(dictionaryId, CompoundDictionary::class.java)
                        newDictionary?.let { compoundDictionary.setMap(it.map()) }
                    }
                }
                logger.info("Dictionary [{}] is reloaded!", dictionaryId)
            }
        }

        @JvmStatic
        fun compileDictionary(
            client: NodeClient,
            repo: DictionaryRepository,
            filter: String?,
            exportFile: Boolean
        ) {
            val localBaseFile = baseFile
            val localConfigFile = configFile
            if (localBaseFile == null || localConfigFile == null) {
                logger.error("DICTIONARY NOT LOADED!")
                return
            }

            val filters = mutableSetOf<String>()
            filter?.trim()?.split(",")?.forEach { filters.add(it.lowercase()) }
            logger.info("Compile Dict types: {}", filters)

            val dictProp = ResourceResolver.readYmlConfig(localConfigFile) ?: return
            val dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST) ?: return
            val basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH)

            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                val dictionaryId = row.optString(ATTR_DICTIONARY_NAME)

                // 필터가 존재하면서 dictionaryId가 없다면 스킵!
                if (filters.isNotEmpty() && !filters.contains(dictionaryId)) {
                    continue
                }

                // 사전과 컴파일된 Count를 Map형태로 받는다.
                val compileDictMap = compileDictionaryOne(repo, dictList, dictionaryId) ?: continue
                @Suppress("UNCHECKED_CAST")
                val sourceDictionary = compileDictMap["dict"] as? SourceDictionary<*>
                if (sourceDictionary != null) {
                    // 엘라스틱서치에 .dsearch_dict_apply 인덱스에 upsert 한다.
                    DictionaryUpsertService.upsertData(client, ".dsearch_dict_apply", compileDictMap)

                    // 파일로 기록. 컴파일.
                    if (exportFile) {
                        val dictFile = getDictionaryFile(localBaseFile, row, basePath)
                        try {
                            FileOutputStream(dictFile).use { ostream ->
                                sourceDictionary.writeTo(ostream)
                                logger.info("DICTIONARY FILE SAVED! {} / {}", dictionaryId, dictFile.absolutePath)
                            }
                        } catch (ignore: Exception) {
                        }
                    }
                }
            }
            logger.debug("DICTIONARY LOAD COMPLETE! [{}]", filter ?: "ALL")
        }

        @JvmStatic
        fun compileDictionaryOne(
            repo: DictionaryRepository,
            dictList: JSONArray,
            dictionaryId: String
        ): MutableMap<String, Any?>? {
            val result = mutableMapOf<String, Any?>()

            // dictList 설정을 스캔하면서 dictionaryId를 찾는다.
            for (inx in 0 until dictList.length()) {
                val row = dictList.optJSONObject(inx)
                val dictId = row.optString(ATTR_DICTIONARY_NAME)
                if (dictionaryId != dictId) continue

                val type = getType(row) ?: continue
                val tokenType = getTokenType(row)
                val label = getLabel(row)
                val seq = getSeq(row)
                val ignoreCase = row.optBoolean(ATTR_DICTIONARY_IGNORECASE, true)

                val source = repo.getSource(dictionaryId)

                // 사전 타입으로 객체생성
                val sourceDictionary: SourceDictionary<*>? = when (type) {
                    DictionaryType.SET -> SetDictionary(ignoreCase)
                    DictionaryType.MAP -> MapDictionary(ignoreCase)
                    DictionaryType.SYNONYM, DictionaryType.SYNONYM_2WAY -> SynonymDictionary(ignoreCase)
                    DictionaryType.SPACE -> SpaceDictionary(ignoreCase)
                    DictionaryType.CUSTOM -> CustomDictionary(ignoreCase)
                    DictionaryType.INVERT_MAP -> InvertMapDictionary(ignoreCase)
                    DictionaryType.COMPOUND -> CompoundDictionary(ignoreCase)
                    else -> null
                }

                // 사전객체에 데이터 입력
                if (sourceDictionary != null) {
                    var cnt = 0
                    while (source.hasNext()) {
                        val data = source.next()
                        val id = data[0]?.toString()?.trim() ?: ""
                        val keyword = data[1]?.toString()?.trim() ?: ""
                        val value = data[2]?.toString()?.trim() ?: ""

                        val line = when (type) {
                            DictionaryType.SYNONYM, DictionaryType.SYNONYM_2WAY -> {
                                if (keyword.isNotEmpty()) "$keyword\t$value" else value
                            }
                            DictionaryType.CUSTOM -> {
                                if (id.isNotEmpty()) "$keyword\t$id" else keyword
                            }
                            else -> {
                                if (value.isNotEmpty()) "$keyword\t$value" else keyword
                            }
                        }
                        sourceDictionary.addSourceLineEntry(line)
                        cnt++
                    }
                    result["cnt"] = cnt
                    logger.info("DICTIONARY LOADED! [{}] / {} / {} / {}", cnt, dictionaryId, type, tokenType)
                }
                result["dict"] = sourceDictionary
                result["type"] = dictId
                result["id"] = dictId
                return result
            }
            return null
        }

        @JvmStatic
        fun getTwowaySynonymWord(
            mainWord: CharSequence,
            synonymMap: Map<CharSequence, Array<CharSequence>>
        ): List<CharSequence>? {
            val map = mutableMapOf<CharSequence, MutableList<CharSequence>>()
            val keys = mutableListOf<CharSequence>()

            val initialValues = mutableListOf<CharSequence>()
            map[mainWord] = initialValues
            keys.addAll(map.keys)
            synonymMap[mainWord]?.let { initialValues.addAll(it) }

            var kinx = 0
            while (kinx < keys.size) {
                val word = keys[kinx]
                val synonyms = synonymMap[word]
                logger.trace("SYN {} : {}", word, synonyms)

                if (synonyms != null) {
                    for (synonym in synonyms) {
                        if (keys.contains(synonym)) continue
                        val subSynonyms = synonymMap[synonym]
                        if (subSynonyms != null && synonyms.isNotEmpty()) {
                            for (subSynonym in subSynonyms) {
                                if (mainWord == subSynonym) {
                                    val newValues = mutableListOf<CharSequence>()
                                    map[synonym] = newValues
                                    keys.add(synonym)
                                    newValues.addAll(subSynonyms)
                                    break
                                }
                            }
                        }
                    }
                }
                kinx++
            }

            if (map.size > 1) {
                normalizeSynonymMap(map)
            }
            logger.trace("MAP:{}", map)

            return if (map.size > 1) {
                keys.clear()
                keys.addAll(TreeSet(map.keys))
                keys
            } else {
                null
            }
        }

        @JvmStatic
        fun normalizeSynonymMap(map: MutableMap<CharSequence, MutableList<CharSequence>>) {
            val keys = mutableListOf<CharSequence>()
            keys.addAll(map.keys)

            // 키값에 없는 동의어 제거
            for (word in keys) {
                val values = map[word] ?: continue
                val iterator = values.iterator()
                while (iterator.hasNext()) {
                    val value = iterator.next()
                    if (!keys.contains(value)) {
                        iterator.remove()
                    }
                }
            }

            val delete = mutableListOf<CharSequence>()
            // 동의어에 없는 키값 제거
            logger.trace("MAP:{}", map)
            for (sinx in keys.indices) {
                val word = keys[sinx]
                for (tinx in keys.indices) {
                    if (sinx == tinx) continue
                    val values = map[keys[tinx]]
                    if (values != null && !values.contains(word)) {
                        delete.add(word)
                        break
                    }
                }
            }
            for (key in delete) {
                map.remove(key)
            }
            logger.trace("MAP:{}", map)
        }

        @JvmStatic
        fun isOneWaySynonym(word: CharSequence, map: Map<CharSequence, Array<CharSequence>>): Boolean {
            if (map.containsKey(word)) {
                val twoway = getTwowaySynonymWord(word, map)
                logger.trace("TWO-WAY {} = {}", word, twoway)
                val synonyms = map[word] ?: return false
                for (value in synonyms) {
                    if (twoway != null && twoway.contains(value)) continue
                    // 단방향이 하나라도 있으면 단방향 동의어
                    logger.trace("ONE-WAY {} -> {}", word, value)
                    return true
                }
            }
            return false
        }

        @JvmStatic
        fun restoreDictionary(repo: DictionaryRepository, index: String) {
            val productNameDictionary = contextStore.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)
                ?: return
            val dictionaryMap = productNameDictionary.getDictionaryMap()

            for ((key, sourceDictionary) in dictionaryMap) {
                logger.debug("KEY:{} / {}", key, sourceDictionary)

                when {
                    sourceDictionary.javaClass.isAssignableFrom(SetDictionary::class.java) -> {
                        val dictionary = sourceDictionary as SetDictionary
                        repo.restore(key, dictionary.ignoreCase(), dictionary.set())
                    }
                    sourceDictionary.javaClass.isAssignableFrom(MapDictionary::class.java) -> {
                        val dictionary = sourceDictionary as MapDictionary
                        val words = mutableSetOf<CharSequence>()
